    /** Back to an empty sim for the next unit. Keeps the registration ids, because SDK objects cache them. */
    public reset(): void {
        this.writes.length = 0;
        this.keyEvents.length = 0;
        this.unsetReads.clear();
        this.errors.length = 0;
        this.gameVars.clear();
        this.values.clear();
        this.simStartMs = 0;
